#include <algorithm>
using namespace std;

int main() {
    string s1 = "Hello", s2 = " World";
    // Concatenation
    string s3 = s1 + s2;
    cout << s3 << endl;
    // Substring
    cout << s3.substr(0, 5) << endl;
    // Reverse
    string rev = s1;
    reverse(rev.begin(), rev.end());
    cout << rev << endl;
    // Search
    size_t pos = s3.find("World");
    if (pos != string::npos) cout << "Found at: " << pos << endl;
    // Compare
    cout << (s1 == "Hello" ? "Equal" : "Not equal") << endl;
    return 0;
}

