#include <iostream>
#include <vector>
#include <string>
using namespace std;

// Naive pattern search
void naiveSearch(string text, string pat) {
    int n = text.size(), m = pat.size();
    for (int i = 0; i <= n - m; i++) {
        int j = 0;
        while (j < m && text[i+j] == pat[j]) j++;
        if (j == m) cout << "Pattern found at index " << i << endl;
    }
}

// KMP
vector<int> buildLPS(string pat) {
    int m = pat.size();
    vector<int> lps(m, 0);
    int len = 0, i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) { lps[i++] = ++len; }
        else if (len) len = lps[len-1];
        else lps[i++] = 0;
    }
    return lps;
}

void kmpSearch(string text, string pat) {
    int n = text.size(), m = pat.size();
    vector<int> lps = buildLPS(pat);
    int i = 0, j = 0;
    while (i < n) {
        if (text[i] == pat[j]) { i++; j++; }
        if (j == m) { cout << "KMP found at: " << i-j << endl; j = lps[j-1]; }
        else if (i < n && text[i] != pat[j]) {
            if (j) j = lps[j-1]; else i++;
        }
    }
}

int main() {
    naiveSearch("AABAACAADAAB", "AABA");
    kmpSearch("AABAACAADAAB", "AABA");
    return 0;
}

